const wf = String($json.workflow?.name ?? 'Unknown workflow').slice(0, 120);
const exec = $json.execution?.id ? String($json.execution.id).slice(0, 40) : undefined;
const where = $json.execution?.lastNodeExecuted ? ' (at ' + String($json.execution.lastNodeExecuted).slice(0, 60) + ')' : '';
let msg = String($json.execution?.error?.message ?? 'The workflow failed.');
msg = msg.replace(/[^\s@]+@[^\s@]+/g, '[address]').replace(/\s+/g, ' ').trim();
msg = (msg + where).slice(0, 200);
const report = { workflow: wf, message: msg };
if (exec) report.executionId = exec;
const body = JSON.stringify(report);
const t = Math.floor(Date.now() / 1000);
return { json: { body, t, toSign: t + '.' + body } };
